<template>
  <el-tree
    v-loading="loading"
    :data="deviceList"
    :props="defaultProps"
    @node-click="handleNodeClick"
    highlight-current
    ref="tree"
    node-key="id"
    :load="loadNode"
    lazy
    :default-expanded-keys="[sourceId]"
  >
    <span
      class="custom-tree-node"
      slot-scope="{ data }"
      :title="displayContent(data)"
    >
      {{ displayContent(data) }}
    </span>
  </el-tree>
</template>

<script>
export default {
  props: {
    driver_protocol: Number,
  },
  data() {
    return {
      loading: false,
      deviceList: [],
      defaultProps: {
        label: "source_name",
        children: "children",
      },
      sourceId: 0,
    };
  },
  created() {
    this.getDeviceList();
  },
  methods: {
    handleNodeClick(data, node) {
      this.$emit("node-click", data, node);
    },
    loadNode(node, resolve) {
      if (node.level === 0) {
        return resolve([]);
      }
      if (node.level === 2 && node.data.driver_protocol == 1)
        return resolve([]);
      node.data.loaded = true; // 标记为已加载，避免重复触发
      this.$api
        .get(`/collect/getDataPropertyList`, {
          params: {
            source_id: node.parent.data.id || node.data.id,
            ...(node.data.driver_protocol != 1 && {
              parent_id: node.data.parent_id || 0,
            }),
          },
        })
        .then(async (res) => {
          if (res.data.data) {
            const data = res.data.data.map((item) => ({
              describe: item.describe,
              id: item.id,
              driver_protocol: node.data.driver_protocol,
              parent_id: item.identifier,
              protocol_config: item.protocol_config
                ? JSON.parse(item.protocol_config)
                : {},
            }));
            return resolve(data);
          } else {
            return resolve([]);
          }
        });
    },
    getDeviceList() {
      this.loading = true;
      this.$api
        .get(`/collect/getDataSourceList`, { params: this.dataSource })
        .then((res) => {
          this.deviceList = (res.data.data || [])
            .map((item) => ({
              ...item,
              id: item.id,
              loaded: false,
            }))
            .filter(
              (item) =>
                !this.driver_protocol ||
                item.driver_protocol === this.driver_protocol
            );
          const targetId = this.$route.query.source_id
            ? Number(this.$route.query.source_id)
            : this.deviceList[0]?.id;

          if (!targetId) return;

          this.sourceId = targetId;
          this.$nextTick(() => this.handleInitialNode(targetId));
        })
        .finally(() => {
          this.loading = false;
        });
    },

    handleInitialNode(targetId) {
      if (this.$route.query.source_id) {
        const targetNode = this.$refs.tree?.getNode(targetId);
        if (!targetNode) return;

        this.loadNode(targetNode, (loadedData) => {
          if (!loadedData?.length) return;

          const targetItem = this.$route.query.pro_id
            ? loadedData.find((item) => item.id == this.$route.query.pro_id)
            : loadedData[0];

          if (!targetItem) return;

          const childNode = this.$refs.tree.getNode(targetItem);
          if (childNode) {
            this.handleNodeClick(targetItem, childNode);
            this.$refs.tree.setCurrentKey(targetItem.id);
          }
        });
      } else {
        const defaultNode = this.deviceList[0];
        if (!defaultNode) return;
        const node = this.$refs.tree.getNode(defaultNode);
        if (node) {
          this.handleNodeClick(defaultNode, node);
          this.$refs.tree.setCurrentKey(this.sourceId);
        }
      }
    },
    displayContent(data) {
      const { describe, driver_protocol, source_name, identifier } = data;
      return describe || (driver_protocol && source_name) || identifier;
    },
  },
};
</script>

<style lang="scss" scoped></style>
